import React from "react"
import ReactDOM from "react-dom/client"
import"./style.css"

const root=ReactDOM.createRoot (document.getElementById("root"))

//Navbar component
function Navbar(){
  return(
    <nav>
      <h1>PERFUMY</h1>
      <ul>
        <li>Home|</li>
        <li>Produts|</li>
        <li>About Us|</li>
        <li>Contact Us</li>
      </ul>
    </nav>
  )
}

//Search Component

function Search(){
  return(
    <div className="searchbar">
      <input type="text" placeholder="Search"/>
    </div>
  )
}

//Product component

root.render(
<div>
  <Navbar></Navbar>
  <Search></Search>
</div>)
